	'in_newsletter_03' => '11',
	'in_newsletter_04' => 'Lettre d’information',
	'in_newsletter_05' => 'Notes du port et nouvelles de la saison, quelques fois par an. Écrivez à office@tomarimarina.example pour être ajouté.',
